# Minimal reference evaluator for a threshold test
import json
from collections import defaultdict
from datetime import datetime, timedelta, timezone

def parse_ts(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc)

def detect(events, min_failures=8, min_users=3, failure_window=timedelta(minutes=10), success_window=timedelta(minutes=15)):
    ordered = sorted(events, key=lambda e: parse_ts(e["timestamp"]))
    failures = defaultdict(list)
    successes = defaultdict(list)
    for e in ordered:
        key = e["source_ip"]
        if e.get("outcome") == "failure":
            failures[key].append(e)
        elif e.get("outcome") == "success":
            successes[key].append(e)

    alerts = []
    for source_ip, items in failures.items():
        for start_event in items:
            start = parse_ts(start_event["timestamp"])
            end = start + failure_window
            window = [e for e in items if start <= parse_ts(e["timestamp"]) <= end]
            users = {e["user"] for e in window}
            if len(window) >= min_failures and len(users) >= min_users:
                later_success = any(
                    start <= parse_ts(s["timestamp"]) <= start + success_window
                    for s in successes.get(source_ip, [])
                )
                if later_success:
                    alerts.append({"source_ip": source_ip, "failure_count": len(window), "unique_users": len(users)})
                break
    return alerts

