#!/usr/bin/env python3
"""Local, deterministic incident-detection reference implementation.

Input: normalized JSONL events
Output: JSON incidents with supporting evidence
Uses only the Python standard library.
"""
from __future__ import annotations

import argparse
import json
import sys
from collections import defaultdict
from dataclasses import dataclass, asdict
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Iterable

REQUIRED_BY_TYPE = {
    "authentication": {"timestamp", "event_id", "user", "source_ip", "target", "outcome"},
    "process": {"timestamp", "event_id", "host", "user", "parent_image", "image", "command_line"},
    "network": {"timestamp", "event_id", "host", "src_ip", "dst_ip", "dst_port", "process_image"},
}

SCRIPT_INTERPRETERS = {"powershell.exe", "pwsh", "wscript.exe", "cscript.exe", "bash", "sh"}
OFFICE_PARENTS = {"winword.exe", "excel.exe", "outlook.exe", "powerpnt.exe"}

@dataclass(frozen=True)
class Event:
    event_id: str
    timestamp: datetime
    event_type: str
    raw: dict[str, Any]

    @property
    def host(self) -> str | None:
        return self.raw.get("host") or self.raw.get("target")


def parse_timestamp(value: str) -> datetime:
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError(f"invalid timestamp: {value}") from exc
    if dt.tzinfo is None:
        raise ValueError(f"timestamp must include a timezone: {value}")
    return dt.astimezone(timezone.utc)


def load_events(path: Path) -> list[Event]:
    events: list[Event] = []
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            try:
                raw = json.loads(line)
                event_type = raw["event_type"]
                event_id = raw["event_id"]
                required = REQUIRED_BY_TYPE.get(event_type, {"timestamp", "event_id", "event_type"})
                missing = sorted(required - raw.keys())
                if missing:
                    raise ValueError(f"missing fields: {', '.join(missing)}")
                ts = parse_timestamp(raw["timestamp"])
                events.append(Event(event_id=event_id, timestamp=ts, event_type=event_type, raw=raw))
            except (KeyError, ValueError, json.JSONDecodeError) as exc:
                raise ValueError(f"invalid event on line {line_number}: {exc}") from exc
    return sorted(events, key=lambda e: e.timestamp)


def detect_authentication_burst(events: Iterable[Event]) -> list[dict[str, Any]]:
    failures: dict[str, list[Event]] = defaultdict(list)
    successes: dict[str, list[Event]] = defaultdict(list)
    for e in events:
        if e.event_type != "authentication":
            continue
        source = e.raw["source_ip"]
        if e.raw["outcome"] == "failure":
            failures[source].append(e)
        elif e.raw["outcome"] == "success":
            successes[source].append(e)

    findings: list[dict[str, Any]] = []
    failure_window = timedelta(minutes=10)
    success_window = timedelta(minutes=15)
    for source, source_failures in failures.items():
        source_failures.sort(key=lambda e: e.timestamp)
        for start_index, start in enumerate(source_failures):
            end = start.timestamp + failure_window
            window = [e for e in source_failures[start_index:] if e.timestamp <= end]
            users = sorted({e.raw["user"] for e in window})
            if len(window) < 8 or len(users) < 3:
                continue
            later_success = next(
                (s for s in successes.get(source, []) if start.timestamp <= s.timestamp <= start.timestamp + success_window),
                None,
            )
            if later_success:
                evidence_ids = [e.event_id for e in window] + [later_success.event_id]
                findings.append({
                    "rule": "authentication-burst-followed-by-success",
                    "source_ip": source,
                    "affected_users": users,
                    "failure_count": len(window),
                    "successful_event_id": later_success.event_id,
                    "evidence_ids": evidence_ids,
                })
                break
    return findings


def detect_suspicious_process(events: Iterable[Event]) -> list[dict[str, Any]]:
    findings: list[dict[str, Any]] = []
    for e in events:
        if e.event_type != "process":
            continue
        image = e.raw["image"].lower().split("\\")[-1]
        parent = e.raw["parent_image"].lower().split("\\")[-1]
        if image in SCRIPT_INTERPRETERS and parent in OFFICE_PARENTS:
            findings.append({
                "rule": "office-to-script-interpreter",
                "host": e.raw["host"],
                "user": e.raw["user"],
                "process_image": e.raw["image"],
                "parent_image": e.raw["parent_image"],
                "command_line": e.raw["command_line"],
                "evidence_ids": [e.event_id],
            })
    return findings


def correlate_process_network(events: list[Event], process_findings: list[dict[str, Any]]) -> list[dict[str, Any]]:
    networks = [e for e in events if e.event_type == "network"]
    by_host: dict[str, list[Event]] = defaultdict(list)
    for e in networks:
        by_host[e.raw["host"]].append(e)

    findings: list[dict[str, Any]] = []
    for pf in process_findings:
        host = pf["host"]
        process_time = None
        for e in events:
            if e.event_id in pf["evidence_ids"]:
                process_time = e.timestamp
                if e.event_type == "process":
                    break
        matching = [
            n for n in by_host.get(host, [])
            if n.raw["process_image"].lower().endswith(pf["process_image"].lower().split("\\")[-1])
            and process_time is not None
            and abs(n.timestamp - process_time) <= timedelta(minutes=10)
        ]
        if matching:
            findings.append({
                "rule": "suspicious-process-with-network-egress",
                "host": host,
                "user": pf["user"],
                "destination_count": len(matching),
                "destinations": [f"{n.raw['dst_ip']}:{n.raw['dst_port']}" for n in matching],
                "evidence_ids": pf["evidence_ids"] + [n.event_id for n in matching],
            })
    return findings


def build_incidents(events: list[Event]) -> list[dict[str, Any]]:
    auth = detect_authentication_burst(events)
    process = detect_suspicious_process(events)
    proc_net = correlate_process_network(events, process)

    incidents: list[dict[str, Any]] = []
    for finding in auth:
        score = 50
        incidents.append({
            "incident_type": finding["rule"],
            "severity": "high" if finding["failure_count"] >= 15 else "medium",
            "confidence": "moderate",
            "score": score,
            "summary": f"Authentication failure burst from {finding['source_ip']} followed by success",
            "evidence": finding,
        })
    for finding in proc_net:
        score = 70
        incidents.append({
            "incident_type": finding["rule"],
            "severity": "high",
            "confidence": "high",
            "score": score,
            "summary": f"Office-launched script interpreter generated network activity on {finding['host']}",
            "evidence": finding,
        })
    return incidents


def main() -> int:
    parser = argparse.ArgumentParser(description="Run deterministic incident detections over normalized JSONL events")
    parser.add_argument("input", type=Path)
    parser.add_argument("--output", type=Path, default=Path("incidents.json"))
    args = parser.parse_args()

    try:
        events = load_events(args.input)
        incidents = build_incidents(events)
        report = {
            "generated_at": datetime.now(timezone.utc).isoformat(),
            "event_count": len(events),
            "incident_count": len(incidents),
            "incidents": incidents,
        }
        args.output.write_text(json.dumps(report, indent=2), encoding="utf-8")
        print(json.dumps({"event_count": len(events), "incident_count": len(incidents), "output": str(args.output)}, indent=2))
        return 0
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())
